<script setup>
defineProps({ date: String, items: Array, counts: Object, filter: String, loading: Boolean });
defineEmits(['update:date', 'refresh', 'filter', 'open']);
const groups = [{ key: 'ALL', label: '全部', hint: '全部币种', class: 'all' }, { key: 'OPEN_LONG', label: '做多', hint: '开多建议', class: 'long' }, { key: 'OPEN_SHORT', label: '做空', hint: '开空建议', class: 'short' }, { key: 'CLOSE_LONG', label: '平多', hint: '多仓退出', class: 'close-long' }, { key: 'CLOSE_SHORT', label: '平空', hint: '空仓退出', class: 'close-short' }, { key: 'WAIT', label: '观望', hint: '等待确认', class: 'wait' }];
function label(value) { return { OPEN_LONG: '做多', OPEN_SHORT: '做空', CLOSE_LONG: '平多', CLOSE_SHORT: '平空', WAIT: '观望' }[value] || '观望'; }
</script>
<template><section class="daily-summary"><div class="view-heading"><div><span class="eyebrow">DAILY OVERVIEW</span><h2>当天分析总结</h2><p>{{ date }} · 每个币种只保留最新结论</p></div><div class="history-filter"><label>分析日期<input :value="date" type="date" :disabled="loading" @change="$emit('update:date', $event.target.value)" /></label><button class="primary" @click="$emit('refresh')" :disabled="loading">{{ loading ? '加载中…' : '刷新总结' }}</button></div></div><div class="summary-metrics position-metrics"><button v-for="group in groups" :key="group.key" class="summary-metric" :class="[group.class, { active: filter === group.key }]" @click="$emit('filter', group.key)" :disabled="loading"><span>{{ group.label }}</span><strong>{{ group.key === 'ALL' ? items.length : counts[group.key] }}</strong><small>{{ group.hint }}</small></button></div><p v-if="loading" class="inline-loading" role="status"><span class="spinner"></span>正在加载当天总结…</p><div v-else-if="items.length" class="daily-list"><button v-for="item in items" :key="item.symbol" class="daily-row" @click="$emit('open', item.record, item.symbol)"><span class="daily-symbol"><b>{{ item.symbol }}</b><small>{{ new Date(item.record.at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }}</small></span><span class="position-action" :class="item.positionRecommendation">{{ label(item.positionRecommendation) }}</span><span class="daily-confidence">置信度 {{ item.confidence }}</span><i>查看详情 ›</i></button></div><p v-else class="empty">{{ date }} 暂无分析结果</p></section></template>
